describe('API Error Handling', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/data', {
            statusCode: 500,
            body: { error: 'Internal Server Error' },
        }).as('getData');
        cy.visit('/'); // Adjust the URL to your application's entry point
    });

    it('should display an error banner when the API call fails', () => {
        cy.wait('@getData');
        cy.get('.error-banner').should('be.visible');
        cy.get('.error-banner').should('contain', 'An error occurred while fetching data.');
    });

    it('should not display the error banner when the API call succeeds', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 200,
            body: { data: 'Success' },
        }).as('getDataSuccess');

        cy.visit('/'); // Reload the page to trigger the successful API call
        cy.wait('@getDataSuccess');
        cy.get('.error-banner').should('not.exist');
    });
});
